window.receiveProjectSource({"path": "src/microservices/web_extraction/services/image_service.py", "lines": ["\"\"\"Best-effort image processing for web extraction articles.", "", "Serves both layer-two (Zyte) and layer-three (manual upload) articles.", "Downloads URL-sourced images when a main image URL is present. When no", "usable image candidate is available, the article is left without image", "rows (the sentinel is still set). Persists outcomes as", "``web_extraction.article_images`` rows and sets", "``articles.images_processed_at`` so Entity Classification can read the", "final state and project to ``accelerate.doc_images``.", "\"\"\"", "", "import asyncio", "import hashlib", "from dataclasses import dataclass, field", "from datetime import UTC, datetime", "from io import BytesIO", "from typing import Any, Optional, cast", "from uuid import UUID", "", "from aiohttp import ClientTimeout", "from PIL import Image, UnidentifiedImageError", "from sqlalchemy import delete, distinct, func, select, tuple_, update", "from sqlalchemy.dialects.postgresql import insert as pg_insert", "", "from common.aws.s3_client import S3Client", "from common.aws.s3_keys import build_s3_key_for_article_image", "from common.config import config as common_cfg", "from common.services.api_helper import APIHelper", "from common.utils.url_helpers import (", "    PinnedAddressResolver,", "    PublicHostResolution,", "    normalize_url,", "    resolve_public_http_host,", ")", "from db.session_manager_async import sessionmanager_datalake", "from microservices.web_extraction.config import config as webex_config", "from microservices.web_extraction.config import test_config as web_test_config", "from microservices.web_extraction.logging import logger", "from microservices.web_extraction.models import Article, ArticleImage", "from microservices.web_extraction.models.enums import (", "    ArticleImageRejectionReason,", "    ArticleImageRole,", "    ArticleImageSource,", "    ArticleImageStatus,", ")", "from microservices.web_extraction.services.helpers.main_image_selection import (", "    Candidate,", "    select_main_image,", ")", "from microservices.web_extraction.services.helpers.markdown import PDFExtractedImage", "", "", "class _RecurrenceQueryError(Exception):", "    \"\"\"Raised when the cross-article logo recurrence read fails (DAT-7895).", "", "    Kept distinct from the best-effort decode/encode failures handled inside", "    ``process_article_images``: a transient DB/proxy failure of this read must", "    propagate to ``process_with_retries`` (so the attempt retries) and must NOT", "    trigger the failure-outcome persist+prune, which would delete this article's", "    prior SUPPLEMENTAL/THUMBNAIL rows.", "    \"\"\"", "", "", "@dataclass", "class _ImageOutcome:", "    \"\"\"Per-role result captured along the processing pipeline.", "", "    One outcome corresponds to one `article_images` row. SUCCEEDED rows", "    have `s3_bucket`/`s3_key`/`byte_count` populated; FAILED/REJECTED", "    rows leave them null and set `rejection_reason`. `source` records the", "    provenance of the image bytes (currently always URL download).", "    \"\"\"", "", "    role: ArticleImageRole", "    status: ArticleImageStatus", "    rejection_reason: Optional[ArticleImageRejectionReason] = None", "    source: ArticleImageSource = ArticleImageSource.URL", "    source_url: Optional[str] = None", "    s3_bucket: Optional[str] = None", "    s3_key: Optional[str] = None", "    width: Optional[int] = None", "    height: Optional[int] = None", "    byte_count: Optional[int] = None", "    image_index: int = 0", "    # True extraction ordinal for body images (MAIN + SUPPLEMENTAL); persisted as", "    # article_images.source_index. MAIN's image_index is pinned to 0, so this is", "    # the only carrier of MAIN's real document-order position. NULL for THUMBNAIL.", "    source_index: Optional[int] = None", "    # Full sha256 hex of the source image bytes for manual-upload body images", "    # (MAIN + SUPPLEMENTAL); persisted as article_images.content_hash. NULL for URL", "    # and THUMBNAIL rows. Feeds the DAT-7895 cross-article logo signal.", "    content_hash: Optional[str] = None", "    position: Optional[float] = None", "", "", "@dataclass", "class _DecodedImage:", "    \"\"\"Successful decode + validation output, ready for encode passes.", "", "    The PIL image is in mode='RGB' and independent of the source bytes", "    (so the underlying `Image.open` context can close before we encode).", "    ``source_url`` is the URL the bytes came from.", "    \"\"\"", "", "    image: Image.Image", "    source_url: Optional[str]", "    width: int", "    height: int", "    image_index: int = 0", "    # Full sha256 hex of the SOURCE image bytes (not the re-encoded output), set", "    # only on the manual-upload decode path. Carries the DAT-7895 content_hash", "    # onto MAIN/SUPPLEMENTAL outcomes; None for URL-sourced images.", "    content_hash: Optional[str] = None", "    position: Optional[float] = None", "", "", "@dataclass(frozen=True)", "class _EncodingSpec:", "    \"\"\"Resolved per-format encode parameters used at call sites.", "", "    Built by `_current_encoding_spec()` from `WEBEX_IMAGE_FORMAT` and the", "    matching format-specific tuning knob. Encapsulates everything an", "    encode + upload step needs to know about the chosen output format.", "    \"\"\"", "", "    pillow_format: str  # \"JPEG\" | \"PNG\" | \"WEBP\"", "    extension: str  # filename suffix without the dot", "    content_type: str", "    save_kwargs: dict = field(default_factory=dict)", "", "", "# Named, identifying request headers for outbound image fetches. Matches", "# the precedent set by Slack (\"Slackbot-LinkExpanding\") and Facebook", "# (\"facebookexternalhit\") of identifying the bot rather than spoofing a", "# browser. Reduces 403s from CDNs that block the default `aiohttp` UA", "# while staying clearly attributable.", "_IMAGE_DOWNLOAD_HEADERS: dict = {", "    \"User-Agent\": \"PolarisIO-WebExtraction/1.0 (+https://www.polarisio.com/robots.txt)\",", "    \"Accept\": \"image/webp,image/png,image/jpeg,image/*;q=0.8,*/*;q=0.5\",", "    \"Accept-Language\": \"en-US,en;q=0.9\",", "}", "", "", "class WebExtractionImageService:", "    \"\"\"Process article MAIN/THUMBNAIL images and persist typed rows + sentinel.\"\"\"", "", "    def __init__(self, api_helper: APIHelper, *, s3_client: Optional[S3Client] = None) -> None:", "        self.api_helper = api_helper", "        self.s3_client = s3_client or S3Client()", "", "    async def process_article_images(", "        self,", "        *,", "        article_id: UUID,", "        article_created_at: datetime,", "        main_image_url: Optional[str],", "        manual_upload_images: Optional[list[PDFExtractedImage]] = None,", "        preserve_existing_main: bool = False,", "    ) -> None:", "        \"\"\"Process main + thumbnail images and persist typed outcomes.", "", "        Manual-upload PDF images, when supplied, can feed the same encode/upload", "        core as URL images. For a new manual-upload article, MAIN is chosen among", "        the qualifying PDF images and derives THUMBNAIL; the rest become", "        SUPPLEMENTAL. In blocks mode (DAT-7895) MAIN is the largest surviving", "        candidate from ``select_main_image`` (icons/logos/repeats/extreme-aspect", "        filtered out, or none), not the first image; with blocks off it stays the", "        legacy first-image-that-decodes. For a manual upload deduplicated to an", "        existing Zyte article, ``preserve_existing_main`` keeps an existing", "        successful MAIN/THUMBNAIL untouched and stores PDF candidates only as", "        SUPPLEMENTAL. If no preserved MAIN exists, MAIN is filled the same way.", "", "        Attempts the URL-based MAIN download when ``main_image_url`` is", "        provided and no manual-upload MAIN has already succeeded. When no image", "        candidate is supplied, no image rows are written. When a candidate URL", "        is supplied but rejected/fails download/decode, the rejection MAIN row", "        is persisted. THUMBNAIL is derived from the successful MAIN.", "", "        Always writes ``articles.images_processed_at`` on every termination", "        path (success, partial, full-fail) so Entity Classification can", "        distinguish \"still in flight\" from \"done with no usable images\"", "        via a bounded poll.", "", "        :param article_id: The article whose image rows are being produced.", "        :type article_id: UUID", "        :param article_created_at: Article creation timestamp used for deterministic S3 key construction.", "        :type article_created_at: datetime", "        :param main_image_url: Optional scraper-extracted source URL for the MAIN role; ``None`` when no candidate was supplied.", "        :type main_image_url: Optional[str]", "        :param manual_upload_images: Optional images extracted from a manually uploaded PDF.", "        :type manual_upload_images: Optional[list[PDFExtractedImage]]", "        :param preserve_existing_main: Whether to keep existing SUCCEEDED MAIN", "            and THUMBNAIL rows and store manual-upload PDF candidates as", "            SUPPLEMENTAL only.", "        :type preserve_existing_main: bool", "        \"\"\"", "        normalized_main = normalize_url(main_image_url)", "        outcomes: list[_ImageOutcome] = []", "        existing_primary_images_succeeded = False", "        recurrence_query_failed = False", "        try:", "            logger.info(", "                \"Starting image processing\",", "                article_id=str(article_id),", "            )", "", "            if preserve_existing_main:", "                existing_primary_images_succeeded = (", "                    await self._has_existing_succeeded_primary_images(article_id=article_id)", "                )", "", "            if manual_upload_images:", "                outcomes.extend(", "                    await self._process_manual_upload_images(", "                        article_id=article_id,", "                        article_created_at=article_created_at,", "                        extracted_images=manual_upload_images,", "                        use_first_as_main=not existing_primary_images_succeeded,", "                    )", "                )", "", "            if (", "                normalized_main is not None", "                and not existing_primary_images_succeeded", "                and not _has_succeeded_main(outcomes)", "            ):", "                rejection_outcome, decoded = await self._download_and_decode_main_image(", "                    article_id=article_id,", "                    source_url=normalized_main,", "                )", "", "                if rejection_outcome is not None:", "                    outcomes.append(rejection_outcome)", "                else:", "                    assert decoded is not None  # narrowing for type checker", "                    main_outcome = await self._encode_and_upload_main(", "                        article_id=article_id,", "                        article_created_at=article_created_at,", "                        decoded=decoded,", "                    )", "                    outcomes.append(main_outcome)", "", "                    if main_outcome.status is ArticleImageStatus.SUCCEEDED:", "                        thumbnail_outcome = await self._encode_and_upload_thumbnail(", "                            article_id=article_id,", "                            article_created_at=article_created_at,", "                            decoded=decoded,", "                        )", "                        outcomes.append(thumbnail_outcome)", "", "            logger.info(", "                \"Completed image processing\",", "                article_id=str(article_id),", "                outcomes=[(o.role.value, o.status.value, o.source.value) for o in outcomes],", "            )", "        except _RecurrenceQueryError as exc:", "            # Transient failure of the cross-article logo read. Do NOT persist a", "            # FAILED-MAIN outcome \u2014 persisting with prune_stale_roles would delete", "            # this article's prior SUPPLEMENTAL/THUMBNAIL rows \u2014 and do NOT swallow:", "            # propagate so process_with_retries retries the whole attempt (and, on", "            # exhaustion, mark_skipped preserves prior rows without pruning).", "            recurrence_query_failed = True", "            logger.warning(", "                \"Cross-article logo query failed; retrying without persisting\",", "                article_id=str(article_id),", "                _exc=exc,", "            )", "            raise", "        except Exception as exc:", "            logger.warning(", "                \"Image processing failed unexpectedly; persisting outcomes anyway\",", "                article_id=str(article_id),", "                _exc=exc,", "            )", "            if not existing_primary_images_succeeded and not any(", "                o.role is ArticleImageRole.MAIN for o in outcomes", "            ):", "                outcomes.append(", "                    _ImageOutcome(", "                        role=ArticleImageRole.MAIN,", "                        status=ArticleImageStatus.FAILED,", "                        rejection_reason=ArticleImageRejectionReason.DECODE_FAILED,", "                        source_url=normalized_main,", "                    )", "                )", "        finally:", "            # Skip persistence entirely when the recurrence read failed: the attempt", "            # is being retried, and persisting/pruning here would be the data loss", "            # we are avoiding.", "            if not recurrence_query_failed:", "                try:", "                    await self._persist_article_image_outcomes(", "                        article_id=article_id,", "                        outcomes=outcomes,", "                        prune_stale_roles=not existing_primary_images_succeeded,", "                    )", "                except Exception as exc:", "                    # ERROR (not WARNING): the outcome list was built but never", "                    # persisted, which leaves `images_processed_at` NULL and EC's", "                    # poll spins through its full timeout. Surfaces as a", "                    # data-integrity signal worth alerting on, not a routine", "                    # transient. Unique message string lets log monitors fire", "                    # specifically on this path.", "                    logger.error(", "                        \"Failed to persist image outcomes; EC will time out polling\",", "                        article_id=str(article_id),", "                        _exc=exc,", "                    )", "", "    async def _process_manual_upload_images(", "        self,", "        *,", "        article_id: UUID,", "        article_created_at: datetime,", "        extracted_images: list[PDFExtractedImage],", "        use_first_as_main: bool,", "    ) -> list[_ImageOutcome]:", "        \"\"\"Turn extracted PDF images into MAIN/THUMBNAIL/SUPPLEMENTAL outcomes.", "", "        :param article_id: Article whose images are being produced.", "        :type article_id: UUID", "        :param article_created_at: Article creation timestamp for S3 keys.", "        :type article_created_at: datetime", "        :param extracted_images: PDF image candidates in source document order.", "        :type extracted_images: list[PDFExtractedImage]", "        :param use_first_as_main: Whether one qualifying PDF image should fill", "            MAIN/THUMBNAIL. When ``True``, MAIN is picked by ``select_main_image``", "            (largest survivor) in blocks mode, or the first image that decodes with", "            blocks off; the rest become SUPPLEMENTAL. When ``False`` (a MAIN already", "            exists), every qualifying PDF image is stored as SUPPLEMENTAL, capped by", "            config.", "        :type use_first_as_main: bool", "        :return: Persistable outcomes for usable PDF images.", "        :rtype: list[_ImageOutcome]", "        \"\"\"", "        blocks_enabled = webex_config.MANUAL_UPLOAD_IMAGE_BLOCKS_ENABLED", "        sorted_images = sorted(extracted_images, key=_pdf_image_sort_key)", "        # Hash each source image once and reuse for both MAIN selection and the", "        # persisted content_hash, so a qualifying image is never hashed twice.", "        content_hash_by_index = {", "            image.image_index: hashlib.sha256(image.image_bytes).hexdigest()", "            for image in sorted_images", "        }", "", "        outcomes: list[_ImageOutcome] = []", "        main_attempted = False", "        supplemental_count = 0", "        # With the reproduction feature on, supplementals are bounded only by the", "        # overall image ceiling; the legacy lower cap applies only when it is off.", "        supplemental_limit = (", "            webex_config.MANUAL_UPLOAD_PDF_MAX_IMAGES", "            if blocks_enabled", "            else max(webex_config.PDF_MAX_SUPPLEMENTAL_IMAGES, 0)", "        )", "        # DAT-7895: in blocks mode, MAIN is chosen by select_main_image over the", "        # reproduced candidates (filter icons/logos/repeats/extreme-aspect, then", "        # largest). A None result means \"no qualifying hero\" -> emit no MAIN (AC4),", "        # which is DISTINCT from the legacy blocks-off path where a None preference", "        # means \"fall back to the first image that decodes\".", "        main_selection_active = use_first_as_main and blocks_enabled", "        preferred_main_index = (", "            await self._select_manual_upload_main_index(", "                article_id=article_id,", "                sorted_images=sorted_images,", "                content_hash_by_index=content_hash_by_index,", "            )", "            if main_selection_active", "            else None", "        )", "        no_main_in_selection_mode = main_selection_active and preferred_main_index is None", "", "        for extracted in sorted_images:", "            decoded = self._decode_manual_upload_image(", "                article_id=article_id,", "                extracted=extracted,", "                content_hash=content_hash_by_index[extracted.image_index],", "            )", "            if decoded is None:", "                continue", "", "            is_main = (", "                use_first_as_main", "                and not main_attempted", "                and not no_main_in_selection_mode", "                and (preferred_main_index is None or extracted.image_index == preferred_main_index)", "            )", "            if is_main:", "                main_attempted = True", "                main_outcome = await self._encode_and_upload_main(", "                    article_id=article_id,", "                    article_created_at=article_created_at,", "                    decoded=decoded,", "                    source=ArticleImageSource.MANUAL_UPLOAD,", "                )", "                outcomes.append(main_outcome)", "                if main_outcome.status is ArticleImageStatus.SUCCEEDED:", "                    thumbnail_outcome = await self._encode_and_upload_thumbnail(", "                        article_id=article_id,", "                        article_created_at=article_created_at,", "                        decoded=decoded,", "                        source=ArticleImageSource.MANUAL_UPLOAD,", "                    )", "                    outcomes.append(thumbnail_outcome)", "                continue", "", "            if supplemental_count >= supplemental_limit:", "                continue", "", "            outcomes.append(", "                await self._encode_and_upload_supplemental(", "                    article_id=article_id,", "                    article_created_at=article_created_at,", "                    decoded=decoded,", "                )", "            )", "            supplemental_count += 1", "", "        return outcomes", "", "    async def _select_manual_upload_main_index(", "        self,", "        *,", "        article_id: UUID,", "        sorted_images: list[PDFExtractedImage],", "        content_hash_by_index: dict[int, str],", "    ) -> Optional[int]:", "        \"\"\"Choose the MAIN ``image_index`` for a manual upload, or ``None`` (DAT-7895).", "", "        Builds candidates from the qualifying (decodable) reproduced images only \u2014", "        picking a non-qualifying ordinal would decode to ``None`` later and strand", "        MAIN \u2014 fetches the cross-article logo set, and defers to the pure", "        ``select_main_image``. Returns ``None`` when no candidate survives the", "        exclusion filters, meaning the document has no hero and earns no MAIN row.", "", "        :param article_id: The article being processed; excluded from its own", "            recurrence count so redelivery is deterministic.", "        :type article_id: UUID", "        :param sorted_images: Extracted images in document order.", "        :type sorted_images: list[PDFExtractedImage]", "        :param content_hash_by_index: Precomputed source-byte hash per image ordinal.", "        :type content_hash_by_index: dict[int, str]", "        :return: The ``image_index`` of the selected MAIN, or ``None``.", "        :rtype: Optional[int]", "        \"\"\"", "        candidates = [", "            Candidate(", "                image_index=image.image_index,", "                width=image.width,", "                height=image.height,", "                position=_normalize_position(image.position),", "                content_hash=content_hash_by_index[image.image_index],", "            )", "            for image in sorted_images", "            if image.qualifies", "        ]", "        if not candidates:", "            return None", "        logo_hashes = await self._fetch_recurring_logo_hashes(", "            content_hashes={candidate.content_hash for candidate in candidates},", "            article_id=article_id,", "        )", "        return select_main_image(candidates, logo_hashes)", "", "    async def _fetch_recurring_logo_hashes(", "        self, *, content_hashes: set[str], article_id: UUID", "    ) -> set[str]:", "        \"\"\"Return the subset of ``content_hashes`` recurring across OTHER articles.", "", "        A hash present on at least ``MANUAL_UPLOAD_LOGO_MIN_ARTICLE_COUNT`` DISTINCT", "        *other* articles is publisher/business chrome (a logo), not a unique", "        photo/chart. Recurrence is a DISTINCT-article count, not a row count, so a", "        logo repeated within a single document does not count as cross-document.", "", "        This article's own rows are excluded from the count so the result is", "        independent of whether a prior run already persisted this article's images", "        \u2014 otherwise a hash sitting at exactly ``min_count - 1`` other articles would", "        flip from kept to excluded on redelivery, changing the MAIN selection and", "        breaking determinism (AC5).", "", "        Scoped to the current document's candidate hashes only (index-backed) and", "        run in its own ``read_session`` that opens and closes before any S3/encode", "        work, honoring the no-transaction-across-I/O invariant. Returns an empty set", "        when there are no candidate hashes. The signal is naturally inert until new", "        uploads accumulate recurrence (no backfill); tune ``MANUAL_UPLOAD_LOGO_MIN_ARTICLE_COUNT``", "        to raise/effectively disable it.", "", "        :param content_hashes: Candidate ``content_hash`` values for the current doc.", "        :type content_hashes: set[str]", "        :param article_id: The current article, excluded from the recurrence count.", "        :type article_id: UUID", "        :return: The cross-article-recurring subset (the ``logo_hashes``).", "        :rtype: set[str]", "        \"\"\"", "        if not content_hashes:", "            return set()", "        min_count = max(webex_config.MANUAL_UPLOAD_LOGO_MIN_ARTICLE_COUNT, 1)", "        try:", "            async with sessionmanager_datalake.read_session() as db:", "                result = await db.execute(", "                    select(ArticleImage.content_hash)", "                    .where(", "                        ArticleImage.content_hash.in_(content_hashes),", "                        ArticleImage.article_id != article_id,", "                    )", "                    .group_by(ArticleImage.content_hash)", "                    .having(func.count(distinct(ArticleImage.article_id)) >= min_count)", "                )", "                recurring = result.scalars().all()", "        except Exception as exc:", "            # Surface as a dedicated error so process_article_images propagates it", "            # to the retry wrapper instead of swallowing it into a FAILED-MAIN", "            # outcome (which would prune prior rows). CancelledError is BaseException", "            # and is intentionally not caught here.", "            raise _RecurrenceQueryError(str(article_id)) from exc", "        return {content_hash for content_hash in recurring if content_hash}", "", "    def _decode_manual_upload_image(", "        self,", "        *,", "        article_id: UUID,", "        extracted: PDFExtractedImage,", "        content_hash: str,", "    ) -> Optional[_DecodedImage]:", "        \"\"\"Decode one extracted PDF image and apply the standard image guards.", "", "        ``content_hash`` is the precomputed sha256 of ``extracted.image_bytes``", "        (hashed once by the caller and reused for both MAIN selection and the", "        persisted row) \u2014 carried onto the returned ``_DecodedImage``.", "        \"\"\"", "        try:", "            with Image.open(BytesIO(extracted.image_bytes)) as source_image:", "                width, height = source_image.size", "                # With the reproduction feature on, the 600x400 bar is replaced by", "                # a degenerate-noise floor so sub-hero body images still persist;", "                # this MUST match the emit gate or a <doc-image> block would leave", "                # a dangling ref. The L2/Zyte gate is untouched when off.", "                if webex_config.MANUAL_UPLOAD_IMAGE_BLOCKS_ENABLED:", "                    dimension_reason = self._validate_manual_upload_reproduction_dimensions(", "                        article_id=article_id,", "                        width=width,", "                        height=height,", "                    )", "                else:", "                    dimension_reason = self._validate_image_dimensions(", "                        article_id=article_id,", "                        width=width,", "                        height=height,", "                    )", "                if dimension_reason is not None:", "                    logger.info(", "                        \"Skipping manual-upload PDF image below storage requirements\",", "                        article_id=str(article_id),", "                        image_index=extracted.image_index,", "                        rejection_reason=dimension_reason.value,", "                    )", "                    return None", "", "                rgb_image = source_image.convert(\"RGB\")", "        except (UnidentifiedImageError, OSError) as exc:", "            logger.warning(", "                \"Failed to decode manual-upload PDF image\",", "                article_id=str(article_id),", "                image_index=extracted.image_index,", "                _exc=exc,", "            )", "            return None", "", "        return _DecodedImage(", "            image=rgb_image,", "            source_url=None,", "            width=width,", "            height=height,", "            image_index=max(extracted.image_index, 0),", "            # Precomputed sha256 of the SOURCE bytes (no S3 re-read): a publisher", "            # logo is byte-identical across uploads, so hashing the original", "            # extracted bytes (not the re-encoded output) is what makes the", "            # cross-article recurrence signal work.", "            content_hash=content_hash,", "            position=_normalize_position(extracted.position),", "        )", "", "    async def _has_existing_succeeded_primary_images(self, *, article_id: UUID) -> bool:", "        \"\"\"Return whether this article already has successful MAIN and THUMBNAIL rows.\"\"\"", "        # read-routing: must-see-own-writes - stays on the writer; this is an", "        # idempotency read-back of image rows this pipeline may have just written,", "        # so it must see its own writes rather than a lagging replica.", "        async with sessionmanager_datalake.read_session() as db:", "            result = await db.execute(", "                select(ArticleImage.role).where(", "                    ArticleImage.article_id == article_id,", "                    ArticleImage.role.in_(", "                        [", "                            ArticleImageRole.MAIN,", "                            ArticleImageRole.THUMBNAIL,", "                        ]", "                    ),", "                    ArticleImage.status == ArticleImageStatus.SUCCEEDED,", "                )", "            )", "        succeeded_roles = set(result.scalars().all())", "        return {", "            ArticleImageRole.MAIN,", "            ArticleImageRole.THUMBNAIL,", "        }.issubset(succeeded_roles)", "", "    async def _download_and_decode_main_image(", "        self,", "        *,", "        article_id: UUID,", "        source_url: str,", "    ) -> tuple[Optional[_ImageOutcome], Optional[_DecodedImage]]:", "        \"\"\"SSRF check, download, format/dimension validate, decode to RGB for MAIN.", "", "        MAIN-only by contract: every rejection branch tags the resulting", "        ``_ImageOutcome`` with ``role=ArticleImageRole.MAIN``. The", "        THUMBNAIL role is always derived from a successful MAIN decode", "        in ``_encode_and_upload_thumbnail`` and never goes through this", "        helper. If a future flow ever needs to download a non-MAIN role", "        directly, parameterize ``role`` here instead of reusing as-is.", "", "        Returns ``(rejection_outcome, None)`` on any rejection or failure", "        before decode, and ``(None, _DecodedImage)`` when the source is", "        successfully decoded into an RGB ``PIL.Image``. The returned", "        image is independent of the source ``BytesIO``, so callers can", "        encode it after the ``Image.open`` context has closed.", "", "        :param article_id: The article whose image is being fetched; used in log context.", "        :type article_id: UUID", "        :param source_url: Public HTTP(S) URL to download the image from.", "        :type source_url: str", "        :return: ``(outcome, None)`` on rejection/failure or ``(None, decoded)`` on success.", "        :rtype: tuple[Optional[_ImageOutcome], Optional[_DecodedImage]]", "        \"\"\"", "        resolution, ssrf_rejection = await resolve_public_http_host(source_url)", "        if ssrf_rejection is not None:", "            logger.warning(", "                \"Blocked non-public image URL to prevent SSRF\",", "                article_id=str(article_id),", "                source_url=source_url,", "                rejection_reason=ssrf_rejection,", "            )", "            return (", "                _ImageOutcome(", "                    role=ArticleImageRole.MAIN,", "                    status=ArticleImageStatus.REJECTED,", "                    rejection_reason=ArticleImageRejectionReason.SSRF_BLOCKED,", "                    source_url=source_url,", "                ),", "                None,", "            )", "", "        resolved_host = cast(PublicHostResolution, resolution)", "        resolver = PinnedAddressResolver(", "            host=resolved_host.host,", "            port=resolved_host.port,", "            addresses=resolved_host.addresses,", "        )", "", "        try:", "            image_bytes, response_headers = await self.api_helper.download_bytes(", "                source_url,", "                headers=_IMAGE_DOWNLOAD_HEADERS,", "                timeout=ClientTimeout(total=webex_config.WEBEX_IMAGE_DOWNLOAD_TIMEOUT_SECONDS),", "                max_bytes=max(webex_config.WEBEX_IMAGE_MAX_DOWNLOAD_BYTES, 1),", "                retry=True,", "                allow_redirects=False,", "                resolver=resolver,", "            )", "        except Exception as exc:", "            status = getattr(exc, \"status\", None)", "            if isinstance(status, int) and 300 <= status < 400:", "                logger.warning(", "                    \"Image download dropped due to 3xx redirect (allow_redirects=False)\",", "                    article_id=str(article_id),", "                    source_url=source_url,", "                    status=status,", "                )", "                reason = ArticleImageRejectionReason.REDIRECT_BLOCKED", "            else:", "                logger.warning(", "                    \"Failed to download image\",", "                    article_id=str(article_id),", "                    source_url=source_url,", "                    _exc=exc,", "                )", "                reason = ArticleImageRejectionReason.DOWNLOAD_FAILED", "            return (", "                _ImageOutcome(", "                    role=ArticleImageRole.MAIN,", "                    status=ArticleImageStatus.FAILED,", "                    rejection_reason=reason,", "                    source_url=source_url,", "                ),", "                None,", "            )", "", "        content_type = self._extract_content_type(response_headers)", "        if content_type is not None:", "            if not content_type.startswith(\"image/\"):", "                logger.warning(", "                    \"Downloaded content is not an image\",", "                    article_id=str(article_id),", "                    source_url=source_url,", "                    content_type=content_type,", "                )", "                return (", "                    _ImageOutcome(", "                        role=ArticleImageRole.MAIN,", "                        status=ArticleImageStatus.REJECTED,", "                        rejection_reason=ArticleImageRejectionReason.NON_IMAGE_CONTENT,", "                        source_url=source_url,", "                    ),", "                    None,", "                )", "            if \"svg\" in content_type:", "                return (", "                    _ImageOutcome(", "                        role=ArticleImageRole.MAIN,", "                        status=ArticleImageStatus.REJECTED,", "                        rejection_reason=ArticleImageRejectionReason.SVG,", "                        source_url=source_url,", "                    ),", "                    None,", "                )", "", "        try:", "            with Image.open(BytesIO(image_bytes)) as source_image:", "                if (", "                    source_image.format is not None", "                    and source_image.format.upper() == \"GIF\"", "                    and bool(getattr(source_image, \"is_animated\", False))", "                ):", "                    return (", "                        _ImageOutcome(", "                            role=ArticleImageRole.MAIN,", "                            status=ArticleImageStatus.REJECTED,", "                            rejection_reason=ArticleImageRejectionReason.ANIMATED_GIF,", "                            source_url=source_url,", "                            width=source_image.width,", "                            height=source_image.height,", "                        ),", "                        None,", "                    )", "", "                width, height = source_image.width, source_image.height", "                dimension_reason = self._validate_image_dimensions(", "                    article_id=article_id,", "                    width=width,", "                    height=height,", "                    source_url=source_url,", "                )", "                if dimension_reason is not None:", "                    return (", "                        _ImageOutcome(", "                            role=ArticleImageRole.MAIN,", "                            status=ArticleImageStatus.REJECTED,", "                            rejection_reason=dimension_reason,", "                            source_url=source_url,", "                            width=width,", "                            height=height,", "                        ),", "                        None,", "                    )", "", "                # `.convert(\"RGB\")` returns a new Image with its own buffer,", "                # independent of the source `BytesIO`. Safe to use after the", "                # `with` block closes.", "                rgb_image = source_image.convert(\"RGB\")", "        except (UnidentifiedImageError, OSError) as exc:", "            logger.warning(", "                \"Failed to decode/normalize image\",", "                article_id=str(article_id),", "                source_url=source_url,", "                _exc=exc,", "            )", "            return (", "                _ImageOutcome(", "                    role=ArticleImageRole.MAIN,", "                    status=ArticleImageStatus.FAILED,", "                    rejection_reason=ArticleImageRejectionReason.DECODE_FAILED,", "                    source_url=source_url,", "                ),", "                None,", "            )", "", "        return (", "            None,", "            _DecodedImage(", "                image=rgb_image,", "                source_url=source_url,", "                width=width,", "                height=height,", "            ),", "        )", "", "    async def _encode_and_upload_main(", "        self,", "        *,", "        article_id: UUID,", "        article_created_at: datetime,", "        decoded: _DecodedImage,", "        source: ArticleImageSource = ArticleImageSource.URL,", "    ) -> _ImageOutcome:", "        \"\"\"Encode the decoded RGB image once in the configured format and upload as main.", "", "        :param article_id: The article whose MAIN image is being persisted.", "        :type article_id: UUID", "        :param article_created_at: Article creation timestamp used for deterministic S3 key construction.", "        :type article_created_at: datetime", "        :param decoded: Validated RGB Pillow image with width/height populated.", "        :type decoded: _DecodedImage", "        :param source: Provenance tag for the resulting outcome; defaults to ``URL``.", "        :type source: ArticleImageSource", "        :return: SUCCEEDED outcome on upload, or FAILED outcome with ``S3_UPLOAD_FAILED`` on upload error.", "        :rtype: _ImageOutcome", "        \"\"\"", "        spec = _current_encoding_spec()", "        # MAIN's image_index is pinned to 0, so carry its true document-order", "        # ordinal in source_index \u2014 but only for manual-upload body images", "        # (a URL MAIN has no PDF ordinal).", "        source_index = decoded.image_index if source is ArticleImageSource.MANUAL_UPLOAD else None", "        # content_hash is manual-upload only (a URL MAIN has no PDF source bytes).", "        content_hash = decoded.content_hash if source is ArticleImageSource.MANUAL_UPLOAD else None", "        # Fit MAIN within the configured bounding box. `.thumbnail()` only", "        # shrinks (never enlarges), so smaller sources pass through at their", "        # original dimensions. `.copy()` is required because the underlying", "        # decoded image is also reused by the THUMBNAIL pass.", "        main_image = decoded.image.copy()", "        main_image.thumbnail(", "            (", "                max(webex_config.WEBEX_MAIN_WIDTH, 1),", "                max(webex_config.WEBEX_MAIN_HEIGHT, 1),", "            )", "        )", "        width, height = main_image.width, main_image.height", "        output = BytesIO()", "        main_image.save(output, format=spec.pillow_format, **spec.save_kwargs)", "        encoded_bytes = output.getvalue()", "", "        s3_key = build_s3_key_for_article_image(", "            article_id, article_created_at, f\"main.{spec.extension}\"", "        )", "        if web_test_config.DEBUG:", "            logger.info(", "                \"DEBUG mode: skipping S3 upload of main image\",", "                article_id=str(article_id),", "                s3_key=s3_key,", "            )", "        else:", "            try:", "                await self.s3_client.put_object(", "                    key=s3_key,", "                    data=encoded_bytes,", "                    content_type=spec.content_type,", "                )", "            except Exception as exc:", "                logger.warning(", "                    \"Failed to upload main image to S3\",", "                    article_id=str(article_id),", "                    s3_key=s3_key,", "                    _exc=exc,", "                )", "                return _ImageOutcome(", "                    role=ArticleImageRole.MAIN,", "                    status=ArticleImageStatus.FAILED,", "                    rejection_reason=ArticleImageRejectionReason.S3_UPLOAD_FAILED,", "                    source=source,", "                    source_url=decoded.source_url,", "                    width=width,", "                    height=height,", "                    source_index=source_index,", "                    content_hash=content_hash,", "                    position=decoded.position,", "                )", "", "        return _ImageOutcome(", "            role=ArticleImageRole.MAIN,", "            status=ArticleImageStatus.SUCCEEDED,", "            source=source,", "            source_url=decoded.source_url,", "            s3_bucket=common_cfg.S3_BUCKET_DATALAKE,", "            s3_key=s3_key,", "            width=width,", "            height=height,", "            byte_count=len(encoded_bytes),", "            source_index=source_index,", "            content_hash=content_hash,", "            position=decoded.position,", "        )", "", "    async def _encode_and_upload_thumbnail(", "        self,", "        *,", "        article_id: UUID,", "        article_created_at: datetime,", "        decoded: _DecodedImage,", "        source: ArticleImageSource = ArticleImageSource.URL,", "    ) -> _ImageOutcome:", "        \"\"\"Resize a copy of the decoded image and upload as the thumbnail.", "", "        Uses the same in-memory decoded buffer as the main encode pass \u2014", "        no second decode. ``.copy()`` is required because ``.thumbnail()``", "        mutates in place.", "", "        :param article_id: The article whose THUMBNAIL is being persisted.", "        :type article_id: UUID", "        :param article_created_at: Article creation timestamp used for deterministic S3 key construction.", "        :type article_created_at: datetime", "        :param decoded: Validated RGB Pillow image; thumbnail is generated from a ``.copy()``.", "        :type decoded: _DecodedImage", "        :param source: Provenance tag for the resulting outcome; defaults to ``URL``.", "        :type source: ArticleImageSource", "        :return: SUCCEEDED outcome on upload, FAILED with ``THUMBNAIL_GENERATION_FAILED``", "            on Pillow errors, or FAILED with ``S3_UPLOAD_FAILED`` on upload error.", "        :rtype: _ImageOutcome", "        \"\"\"", "        spec = _current_encoding_spec()", "        try:", "            thumb_image = decoded.image.copy()", "            thumb_image.thumbnail(", "                (", "                    max(webex_config.WEBEX_THUMBNAIL_WIDTH, 1),", "                    max(webex_config.WEBEX_THUMBNAIL_HEIGHT, 1),", "                )", "            )", "            width, height = thumb_image.width, thumb_image.height", "            output = BytesIO()", "            thumb_image.save(output, format=spec.pillow_format, **spec.save_kwargs)", "            thumb_bytes = output.getvalue()", "        except (UnidentifiedImageError, OSError) as exc:", "            logger.warning(", "                \"Failed to generate thumbnail from decoded image\",", "                article_id=str(article_id),", "                _exc=exc,", "            )", "            return _ImageOutcome(", "                role=ArticleImageRole.THUMBNAIL,", "                status=ArticleImageStatus.FAILED,", "                rejection_reason=ArticleImageRejectionReason.THUMBNAIL_GENERATION_FAILED,", "                source=source,", "                position=decoded.position,", "            )", "", "        s3_key = build_s3_key_for_article_image(", "            article_id, article_created_at, f\"thumbnail.{spec.extension}\"", "        )", "        if web_test_config.DEBUG:", "            logger.info(", "                \"DEBUG mode: skipping S3 upload of thumbnail image\",", "                article_id=str(article_id),", "                s3_key=s3_key,", "            )", "        else:", "            try:", "                await self.s3_client.put_object(", "                    key=s3_key,", "                    data=thumb_bytes,", "                    content_type=spec.content_type,", "                )", "            except Exception as exc:", "                logger.warning(", "                    \"Failed to upload thumbnail to S3\",", "                    article_id=str(article_id),", "                    s3_key=s3_key,", "                    _exc=exc,", "                )", "                return _ImageOutcome(", "                    role=ArticleImageRole.THUMBNAIL,", "                    status=ArticleImageStatus.FAILED,", "                    rejection_reason=ArticleImageRejectionReason.S3_UPLOAD_FAILED,", "                    source=source,", "                    width=width,", "                    height=height,", "                    position=decoded.position,", "                )", "", "        return _ImageOutcome(", "            role=ArticleImageRole.THUMBNAIL,", "            status=ArticleImageStatus.SUCCEEDED,", "            source=source,", "            s3_bucket=common_cfg.S3_BUCKET_DATALAKE,", "            s3_key=s3_key,", "            width=width,", "            height=height,", "            byte_count=len(thumb_bytes),", "            position=decoded.position,", "        )", "", "    async def _encode_and_upload_supplemental(", "        self,", "        *,", "        article_id: UUID,", "        article_created_at: datetime,", "        decoded: _DecodedImage,", "    ) -> _ImageOutcome:", "        \"\"\"Resize and upload a manual-upload PDF image as SUPPLEMENTAL.\"\"\"", "        spec = _current_encoding_spec()", "        supplemental_image = decoded.image.copy()", "        supplemental_image.thumbnail(", "            (", "                max(webex_config.WEBEX_MAIN_WIDTH, 1),", "                max(webex_config.WEBEX_MAIN_HEIGHT, 1),", "            )", "        )", "        width, height = supplemental_image.width, supplemental_image.height", "        output = BytesIO()", "        supplemental_image.save(output, format=spec.pillow_format, **spec.save_kwargs)", "        encoded_bytes = output.getvalue()", "", "        s3_key = build_s3_key_for_article_image(", "            article_id,", "            article_created_at,", "            f\"supplemental-{decoded.image_index}.{spec.extension}\",", "        )", "        if web_test_config.DEBUG:", "            logger.info(", "                \"DEBUG mode: skipping S3 upload of supplemental image\",", "                article_id=str(article_id),", "                s3_key=s3_key,", "            )", "        else:", "            try:", "                await self.s3_client.put_object(", "                    key=s3_key,", "                    data=encoded_bytes,", "                    content_type=spec.content_type,", "                )", "            except Exception as exc:", "                logger.warning(", "                    \"Failed to upload supplemental image to S3\",", "                    article_id=str(article_id),", "                    s3_key=s3_key,", "                    image_index=decoded.image_index,", "                    _exc=exc,", "                )", "                return _ImageOutcome(", "                    role=ArticleImageRole.SUPPLEMENTAL,", "                    status=ArticleImageStatus.FAILED,", "                    rejection_reason=ArticleImageRejectionReason.S3_UPLOAD_FAILED,", "                    source=ArticleImageSource.MANUAL_UPLOAD,", "                    width=width,", "                    height=height,", "                    image_index=decoded.image_index,", "                    source_index=decoded.image_index,", "                    content_hash=decoded.content_hash,", "                    position=decoded.position,", "                )", "", "        return _ImageOutcome(", "            role=ArticleImageRole.SUPPLEMENTAL,", "            status=ArticleImageStatus.SUCCEEDED,", "            source=ArticleImageSource.MANUAL_UPLOAD,", "            s3_bucket=common_cfg.S3_BUCKET_DATALAKE,", "            s3_key=s3_key,", "            width=width,", "            height=height,", "            byte_count=len(encoded_bytes),", "            image_index=decoded.image_index,", "            source_index=decoded.image_index,", "            content_hash=decoded.content_hash,", "            position=decoded.position,", "        )", "", "    async def mark_skipped(self, *, article_id: UUID) -> None:", "        \"\"\"Mark images as terminally processed without writing any rows.", "", "        Used for give-up paths that intentionally skip image work", "        (``WEBEX_IMAGE_PROCESSING_ENABLED=False``, image-pool acquire", "        timeout, retry exhaustion) so EC's poll exits early instead of", "        timing out. Does not prune existing rows \u2014 these paths are", "        \"give up, don't undo prior successful work.\"", "", "        :param article_id: The article whose ``images_processed_at`` sentinel should be set.", "        :type article_id: UUID", "        \"\"\"", "        await self._persist_article_image_outcomes(article_id=article_id, outcomes=[])", "", "    async def _persist_article_image_outcomes(", "        self,", "        *,", "        article_id: UUID,", "        outcomes: list[_ImageOutcome],", "        prune_stale_roles: bool = False,", "    ) -> None:", "        \"\"\"Upsert one row per outcome and set the article's sentinel timestamp.", "", "        Uses ON CONFLICT (article_id, role, image_index) DO UPDATE so that SQS", "        redelivery (which re-runs image processing) cleanly overwrites", "        any rows from a prior partial attempt.", "", "        :param article_id: The article whose image rows + sentinel are being persisted.", "        :type article_id: UUID", "        :param outcomes: One outcome per row to upsert; an empty list still bumps", "            ``articles.images_processed_at`` so EC stops polling.", "        :type outcomes: list[_ImageOutcome]", "        :param prune_stale_roles: When ``True``, deletes rows for ``article_id`` whose", "            ``(role, image_index)`` key is not present in ``outcomes`` before upserting.", "            Used by ``process_article_images`` so a redelivery that produces a different", "            image set cannot leave stale rows from an earlier attempt visible to EC.", "            ``mark_skipped`` leaves this off.", "        :type prune_stale_roles: bool", "        \"\"\"", "        # Invariant: the image rows and the sentinel must be written in ONE", "        # transaction. `common.helpers.doc_images_projection.", "        # write_doc_images_from_article_images` relies on it -- a poll that has", "        # not seen the sentinel can then never observe a partial row set, so it", "        # projects whatever is committed without further guarding. Splitting", "        # this write would silently make a partial projection reachable;", "        # `test_persist_writes_rows_and_sentinel_in_one_transaction` fails if", "        # the single `write_session` below is split in two.", "        async with sessionmanager_datalake.write_session() as db:", "            if prune_stale_roles:", "                outcome_keys = [(outcome.role, outcome.image_index) for outcome in outcomes]", "                stale_filter = ArticleImage.article_id == article_id", "                if outcome_keys:", "                    stale_filter = stale_filter & tuple_(", "                        ArticleImage.role,", "                        ArticleImage.image_index,", "                    ).notin_(outcome_keys)", "                await db.execute(delete(ArticleImage).where(stale_filter))", "            for outcome in outcomes:", "                values = {", "                    \"article_id\": article_id,", "                    \"role\": outcome.role,", "                    \"status\": outcome.status,", "                    \"rejection_reason\": outcome.rejection_reason,", "                    \"source\": outcome.source,", "                    \"source_url\": outcome.source_url,", "                    \"s3_bucket\": outcome.s3_bucket,", "                    \"s3_key\": outcome.s3_key,", "                    \"width\": outcome.width,", "                    \"height\": outcome.height,", "                    \"byte_count\": outcome.byte_count,", "                    \"image_index\": outcome.image_index,", "                    \"source_index\": outcome.source_index,", "                    \"content_hash\": outcome.content_hash,", "                    \"position\": outcome.position,", "                }", "                stmt = pg_insert(ArticleImage).values(**values)", "                stmt = stmt.on_conflict_do_update(", "                    constraint=\"uq_webex_article_images_article_role_index\",", "                    set_={", "                        \"status\": stmt.excluded.status,", "                        \"rejection_reason\": stmt.excluded.rejection_reason,", "                        \"source\": stmt.excluded.source,", "                        \"source_url\": stmt.excluded.source_url,", "                        \"s3_bucket\": stmt.excluded.s3_bucket,", "                        \"s3_key\": stmt.excluded.s3_key,", "                        \"width\": stmt.excluded.width,", "                        \"height\": stmt.excluded.height,", "                        \"byte_count\": stmt.excluded.byte_count,", "                        \"source_index\": stmt.excluded.source_index,", "                        \"content_hash\": stmt.excluded.content_hash,", "                        \"position\": stmt.excluded.position,", "                        \"updated_at\": datetime.now(UTC),", "                    },", "                )", "                await db.execute(stmt)", "", "            await db.execute(", "                update(Article)", "                .where(Article.id == article_id)", "                .values(images_processed_at=datetime.now(UTC))", "            )", "            # write_session commits on normal exit.", "", "    @staticmethod", "    def _extract_content_type(headers: dict[str, Any]) -> Optional[str]:", "        \"\"\"Extract lowercase content-type without parameters from response headers.", "", "        :param headers: Response headers from the image download.", "        :type headers: dict[str, Any]", "        :return: Lowercased content-type with parameters stripped, or ``None`` if absent or non-string.", "        :rtype: Optional[str]", "        \"\"\"", "        raw = headers.get(\"Content-Type\")", "        if not isinstance(raw, str):", "            return None", "        value = raw.split(\";\", 1)[0].strip().lower()", "        return value or None", "", "    @staticmethod", "    def _validate_image_dimensions(", "        *,", "        article_id: UUID,", "        width: int,", "        height: int,", "        source_url: Optional[str] = None,", "    ) -> Optional[ArticleImageRejectionReason]:", "        \"\"\"Apply max-pixel and min-dimension guards to a decoded image.", "", "        Logs a warning at the rejection point so failures surface in", "        observability. The URL path persists rejection rows, but a log", "        line is still useful for debugging size issues.", "", "        :param article_id: The article whose image is being validated; used in log context.", "        :type article_id: UUID", "        :param width: Decoded image width in pixels.", "        :type width: int", "        :param height: Decoded image height in pixels.", "        :type height: int", "        :param source_url: Optional source URL, included in log context when present.", "        :type source_url: Optional[str]", "        :return: ``MAX_PIXELS_EXCEEDED`` or ``TOO_SMALL`` when a guard", "            trips, ``None`` when the image passes both checks.", "        :rtype: Optional[ArticleImageRejectionReason]", "        \"\"\"", "        max_pixels = max(webex_config.WEBEX_IMAGE_MAX_PIXELS, 1)", "        if width * height > max_pixels:", "            logger.warning(", "                \"Image exceeds max pixel guard\",", "                article_id=str(article_id),", "                source_url=source_url,", "                image_width=width,", "                image_height=height,", "                max_pixels=max_pixels,", "            )", "            return ArticleImageRejectionReason.MAX_PIXELS_EXCEEDED", "", "        min_width = max(webex_config.WEBEX_IMAGE_MIN_WIDTH, 1)", "        min_height = max(webex_config.WEBEX_IMAGE_MIN_HEIGHT, 1)", "        if width < min_width or height < min_height:", "            logger.warning(", "                \"Image below minimum dimensions\",", "                article_id=str(article_id),", "                source_url=source_url,", "                image_width=width,", "                image_height=height,", "            )", "            return ArticleImageRejectionReason.TOO_SMALL", "", "        return None", "", "    @staticmethod", "    def _validate_manual_upload_reproduction_dimensions(", "        *,", "        article_id: UUID,", "        width: int,", "        height: int,", "    ) -> Optional[ArticleImageRejectionReason]:", "        \"\"\"Storage gate for faithful manual-upload reproduction (blocks feature on).", "", "        Applies the max-pixel guard and the degenerate-noise floor", "        (``MANUAL_UPLOAD_IMAGE_MIN_DIMENSION``) instead of the 600x400 hero bar,", "        matching the emit gate so a ``<doc-image>`` block always resolves to a", "        stored row. Degenerate objects and repeated chrome are already dropped", "        upstream in ``extract_pdf_images``.", "", "        :param article_id: The article whose image is being validated; log context.", "        :type article_id: UUID", "        :param width: Decoded image width in pixels.", "        :type width: int", "        :param height: Decoded image height in pixels.", "        :type height: int", "        :return: ``MAX_PIXELS_EXCEEDED`` or ``TOO_SMALL`` when a guard trips,", "            ``None`` when the image is reproducible.", "        :rtype: Optional[ArticleImageRejectionReason]", "        \"\"\"", "        max_pixels = max(webex_config.WEBEX_IMAGE_MAX_PIXELS, 1)", "        if width * height > max_pixels:", "            logger.warning(", "                \"Image exceeds max pixel guard\",", "                article_id=str(article_id),", "                image_width=width,", "                image_height=height,", "                max_pixels=max_pixels,", "            )", "            return ArticleImageRejectionReason.MAX_PIXELS_EXCEEDED", "", "        min_dimension = max(webex_config.MANUAL_UPLOAD_IMAGE_MIN_DIMENSION, 1)", "        if min(width, height) < min_dimension:", "            logger.warning(", "                \"Image below reproduction noise floor\",", "                article_id=str(article_id),", "                image_width=width,", "                image_height=height,", "                min_dimension=min_dimension,", "            )", "            return ArticleImageRejectionReason.TOO_SMALL", "", "        return None", "", "", "def _has_succeeded_main(outcomes: list[_ImageOutcome]) -> bool:", "    \"\"\"Return True when outcomes already contain a successful MAIN row.\"\"\"", "    return any(", "        outcome.role is ArticleImageRole.MAIN and outcome.status is ArticleImageStatus.SUCCEEDED", "        for outcome in outcomes", "    )", "", "", "def _normalize_position(position: Optional[float]) -> Optional[float]:", "    \"\"\"Clamp optional document image position into the persisted 0-1 interval.\"\"\"", "    if position is None:", "        return None", "    try:", "        normalized = float(position)", "    except (TypeError, ValueError):", "        return None", "    if normalized != normalized:", "        return None", "    return min(max(normalized, 0.0), 1.0)", "", "", "def _pdf_image_sort_key(extracted: PDFExtractedImage) -> tuple[float, int]:", "    \"\"\"Sort PDF images top-to-bottom when position is available.\"\"\"", "    position = _normalize_position(extracted.position)", "    return (position if position is not None else float(\"inf\"), extracted.image_index)", "", "", "def _current_encoding_spec() -> _EncodingSpec:", "    \"\"\"Resolve the encoding spec for `WEBEX_IMAGE_FORMAT` and its tuning knobs.", "", "    Each call reads config so tests can monkey-patch the format at runtime.", "", "    :return: Pillow format, file extension, content-type, and ``save()`` kwargs", "        for the configured output format (JPEG, PNG, or WEBP). Falls back to PNG", "        for any unexpected ``WEBEX_IMAGE_FORMAT`` value.", "    :rtype: _EncodingSpec", "    \"\"\"", "    image_format = webex_config.WEBEX_IMAGE_FORMAT.lower()", "", "    if image_format == \"jpeg\":", "        quality = min(max(webex_config.WEBEX_IMAGE_JPEG_QUALITY, 1), 95)", "        return _EncodingSpec(", "            pillow_format=\"JPEG\",", "            extension=\"jpg\",", "            content_type=\"image/jpeg\",", "            save_kwargs={\"quality\": quality, \"optimize\": True},", "        )", "", "    if image_format == \"webp\":", "        quality = min(max(webex_config.WEBEX_IMAGE_WEBP_QUALITY, 1), 100)", "        save_kwargs: dict = {\"quality\": quality}", "        if webex_config.WEBEX_IMAGE_WEBP_LOSSLESS:", "            save_kwargs[\"lossless\"] = True", "        return _EncodingSpec(", "            pillow_format=\"WEBP\",", "            extension=\"webp\",", "            content_type=\"image/webp\",", "            save_kwargs=save_kwargs,", "        )", "", "    # Default branch: PNG (also handles any unexpected value, since", "    # config-time parsing already normalized to a supported format).", "    compress_level = min(max(webex_config.WEBEX_IMAGE_PNG_COMPRESS_LEVEL, 0), 9)", "    return _EncodingSpec(", "        pillow_format=\"PNG\",", "        extension=\"png\",", "        content_type=\"image/png\",", "        save_kwargs={\"compress_level\": compress_level, \"optimize\": True},", "    )", "", "", "async def process_with_retries(", "    image_service: \"WebExtractionImageService\",", "    *,", "    article_id: UUID,", "    article_created_at: datetime,", "    main_image_url: Optional[str],", "    max_attempts: int,", "    manual_upload_images: Optional[list[PDFExtractedImage]] = None,", "    preserve_existing_main: bool = False,", ") -> None:", "    \"\"\"Run ``process_article_images`` with retries; mark sentinel on exhaustion.", "", "    Wraps the per-article image pipeline with a small retry budget so", "    transient DB or asyncio failures escaping ``process_article_images``", "    don't permanently leave ``images_processed_at`` NULL. Internal", "    transient errors (image download, S3 PUT) are still retried by their", "    respective lower-level helpers; this wrapper exists for the *outer*", "    failure modes \u2014 DB connection drop during", "    ``_persist_article_image_outcomes``, etc.", "", "    On every attempt failing, performs a final ``mark_skipped`` so EC's", "    poll exits via the sentinel rather than timing out. ``CancelledError``", "    is propagated unchanged so shutdown drain still works.", "", "    :param image_service: Service instance whose pipeline to run.", "    :type image_service: WebExtractionImageService", "    :param article_id: Article whose image rows are being produced.", "    :type article_id: UUID", "    :param article_created_at: Article creation timestamp for S3 key construction.", "    :type article_created_at: datetime", "    :param main_image_url: Optional Zyte-extracted source URL for the MAIN role.", "    :type main_image_url: Optional[str]", "    :param max_attempts: Total attempts (initial + retries) before giving up.", "    :type max_attempts: int", "    :param manual_upload_images: Optional images extracted from a manually uploaded PDF.", "    :type manual_upload_images: Optional[list[PDFExtractedImage]]", "    :param preserve_existing_main: Whether to preserve existing successful", "        MAIN and THUMBNAIL rows and store PDF images as SUPPLEMENTAL only.", "    :type preserve_existing_main: bool", "    \"\"\"", "    attempts = max(max_attempts, 1)", "    last_exc: Optional[BaseException] = None", "    for attempt in range(1, attempts + 1):", "        try:", "            await image_service.process_article_images(", "                article_id=article_id,", "                article_created_at=article_created_at,", "                main_image_url=main_image_url,", "                manual_upload_images=manual_upload_images,", "                preserve_existing_main=preserve_existing_main,", "            )", "            return", "        except asyncio.CancelledError:", "            raise", "        except Exception as exc:", "            last_exc = exc", "            logger.warning(", "                \"Image processing attempt failed; will retry\",", "                article_id=str(article_id),", "                attempt=attempt,", "                max_attempts=attempts,", "                _exc=exc,", "            )", "            if attempt < attempts:", "                # Exponential backoff: 1s, 2s, 4s, ...", "                await asyncio.sleep(2 ** (attempt - 1))", "", "    logger.error(", "        \"Image processing exhausted retries; marking sentinel skipped\",", "        article_id=str(article_id),", "        max_attempts=attempts,", "        _exc=last_exc,", "    )", "    try:", "        await image_service.mark_skipped(article_id=article_id)", "    except Exception as exc:", "        # ERROR (matches the persist-failure branch inside", "        # process_article_images): the sentinel was never written, so", "        # EC's poll spins through its full timeout. Same data-integrity", "        # signal \u2014 log monitors should fire on either path.", "        logger.error(", "            \"Failed to mark sentinel after retry exhaustion; EC will time out\",", "            article_id=str(article_id),", "            _exc=exc,", "        )"], "blocks": [{"start": 1, "end": 52, "label": "Imports and module setup"}, {"start": 53, "end": 63, "label": "class _RecurrenceQueryError"}, {"start": 64, "end": 95, "label": "class _ImageOutcome"}, {"start": 96, "end": 116, "label": "class _DecodedImage"}, {"start": 117, "end": 143, "label": "class _EncodingSpec"}, {"start": 144, "end": 146, "label": "class WebExtractionImageService"}, {"start": 147, "end": 150, "label": "WebExtractionImageService.__init__"}, {"start": 151, "end": 309, "label": "WebExtractionImageService.process_article_images"}, {"start": 310, "end": 419, "label": "WebExtractionImageService._process_manual_upload_images"}, {"start": 420, "end": 463, "label": "WebExtractionImageService._select_manual_upload_main_index"}, {"start": 464, "end": 516, "label": "WebExtractionImageService._fetch_recurring_logo_hashes"}, {"start": 517, "end": 581, "label": "WebExtractionImageService._decode_manual_upload_image"}, {"start": 582, "end": 605, "label": "WebExtractionImageService._has_existing_succeeded_primary_images"}, {"start": 606, "end": 795, "label": "WebExtractionImageService._download_and_decode_main_image"}, {"start": 796, "end": 890, "label": "WebExtractionImageService._encode_and_upload_main"}, {"start": 891, "end": 988, "label": "WebExtractionImageService._encode_and_upload_thumbnail"}, {"start": 989, "end": 1063, "label": "WebExtractionImageService._encode_and_upload_supplemental"}, {"start": 1064, "end": 1077, "label": "WebExtractionImageService.mark_skipped"}, {"start": 1078, "end": 1166, "label": "WebExtractionImageService._persist_article_image_outcomes"}, {"start": 1167, "end": 1181, "label": "WebExtractionImageService._extract_content_type"}, {"start": 1182, "end": 1233, "label": "WebExtractionImageService._validate_image_dimensions"}, {"start": 1234, "end": 1283, "label": "WebExtractionImageService._validate_manual_upload_reproduction_dimensions"}, {"start": 1284, "end": 1291, "label": "def _has_succeeded_main"}, {"start": 1292, "end": 1304, "label": "def _normalize_position"}, {"start": 1305, "end": 1310, "label": "def _pdf_image_sort_key"}, {"start": 1311, "end": 1354, "label": "def _current_encoding_spec"}, {"start": 1355, "end": 1439, "label": "def process_with_retries"}], "lineCount": 1439, "sha256": "e413bf24b6bfa41a639030a0f1ffacc476b2e994c2df53bf84887c3534654241", "endsWithNewline": true});
